        else
            while (first != last) {
                NodeBase* victim = first; first = Next(first);
                Node* y = static_cast<Node*>(Rebalance_for_erase(victim, header->parent, header->left, header->right));
                y->value.~Value();
                if (y) std::free(y);
                --count;
            }
